      "kind": "definition",
      "type": "{R : Type u_1} →\n  {M : Type u_2} →\n    [inst : CommSemiring R] → [inst_1 : AddCommMonoid M] → [Module R M] → {ι : Type u_4} → (ι → M) → (ι →₀ R) → M"
    },
    {
      "name": "Finsupp.linearCombination",
      "module_name": "Mathlib.LinearAlgebra.Finsupp.LinearCombination",
      "kind": "definition",
      "type": "{α : Type u_1} →\n  {M : Type u_2} →\n    (R : Type u_5) →\n      [inst : Semiring R] → [inst_1 : AddCommMonoid M] → [inst_2 : Module R M] → (α → M) → (α →₀ R) →ₗ[R] M"
    },
    {
      "name": "Finsupp.linearCombination_option",
      "module_name": "Mathlib.LinearAlgebra.Finsupp.LinearCombination",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {M : Type u_2} (R : Type u_5) [inst : Semiring R] [inst_1 : AddCommMonoid M] [inst_2 : Module R M]\n  (v : Option α → M) (f : Option α →₀ R),\n  (Finsupp.linearCombination R v) f = f none • v none + (Finsupp.linearCombination R (v ∘ some)) f.some"
    },
    {
      "name": "Finsupp.apply_linearCombination",
      "module_name": "Mathlib.LinearAlgebra.Finsupp.LinearCombination",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {M : Type u_2} (R : Type u_5) [inst : Semiring R] [inst_1 : AddCommMonoid M] [inst_2 : Module R M]\n  {M' : Type u_8} [inst_3 : AddCommMonoid M'] [inst_4 : Module R M'] (f : M →ₗ[R] M') (v : α → M) (l : α →₀ R),\n  f ((Finsupp.linearCombination R v) l) = (Finsupp.linearCombination R (⇑f ∘ v)) l"
    },
    {
      "name": "Fintype.linearCombination",
      "module_name": "Mathlib.LinearAlgebra.Finsupp.LinearCombination",
      "kind": "definition",
      "type": "{α : Type u_1} →\n  {M : Type u_2} →\n    (R : Type u_3) →\n      [Fintype α] → [inst : Semiring R] → [inst_1 : AddCommMonoid M] → [inst_2 : Module R M] → (α → M) → (α → R) →ₗ[R] M"
    },
    {
      "name": "Finsupp.lmapDomain_linearCombination",
      "module_name": "Mathlib.LinearAlgebra.Finsupp.LinearCombination",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {M : Type u_2} (R : Type u_5) [inst : Semiring R] [inst_1 : AddCommMonoid M] [inst_2 : Module R M]\n  {α' : Type u_7} {M' : Type u_8} [inst_3 : AddCommMonoid M'] [inst_4 : Module R M'] {v : α → M} {v' : α' → M'}\n  (f : α → α') (g : M →ₗ[R] M'),\n  (∀ (i : α), g (v i) = v' (f i)) →\n    Finsupp.linearCombination R v' ∘ₗ Finsupp.lmapDomain R R f = g ∘ₗ Finsupp.linearCombination R v"
    },
    {
      "name": "Finsupp.linearCombination_apply",
      "module_name": "Mathlib.LinearAlgebra.Finsupp.LinearCombination",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {M : Type u_2} (R : Type u_5) [inst : Semiring R] [inst_1 : AddCommMonoid M] [inst_2 : Module R M]\n  {v : α → M} (l : α →₀ R), (Finsupp.linearCombination R v) l = l.sum fun i a => a • v i"
    },
    {
      "name": "Fintype.linearCombination_apply",
      "module_name": "Mathlib.LinearAlgebra.Finsupp.LinearCombination",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {M : Type u_2} (R : Type u_3) [inst : Fintype α] [inst_1 : Semiring R] [inst_2 : AddCommMonoid M]\n  [inst_3 : Module R M] (v : α → M) (f : α → R), (Fintype.linearCombination R v) f = ∑ i, f i • v i"
    },
    {
      "name": "CompactlySupportedContinuousMap.monotone_of_nnreal",
      "module_name": "Mathlib.MeasureTheory.Integral.RieszMarkovKakutani.Basic",
      "kind": "theorem",
      "type": "∀ {X : Type u_1} [inst : TopologicalSpace X] (Λ : CompactlySupportedContinuousMap X NNReal →ₗ[NNReal] NNReal),\n  Monotone ⇑Λ"
    },
    {
      "name": "Finsupp.linearCombination_eq_fintype_linearCombination",
      "module_name": "Mathlib.LinearAlgebra.Finsupp.LinearCombination",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {M : Type u_2} (R : Type u_3) [inst : Fintype α] [inst_1 : Semiring R] [inst_2 : AddCommMonoid M]\n  [inst_3 : Module R M] (v : α → M),\n  Finsupp.linearCombination R v ∘ₗ ↑(Finsupp.linearEquivFunOnFinite R R α).symm = Fintype.linearCombination R v"
    }
  ]
}
